    #[test]
    fn runtime_tenant_id_defaults_and_parses_env_override() {
        let default_tenant = runtime_tenant_id_from_lookup(|_| None).expect("default tenant id");
        assert_eq!(
            default_tenant,
            Uuid::parse_str(DEFAULT_TENANT_ID).expect("valid default tenant id")
        );

        let configured_tenant = Uuid::parse_str("00000000-0000-4000-8000-000000000042")
            .expect("valid configured tenant id");
        let parsed = runtime_tenant_id_from_lookup(|key| {
            if key == "MANDOFORGE_TENANT_ID" {
                Some(format!(" {configured_tenant} "))
            } else {
                None
            }
        })
        .expect("configured tenant id");
        assert_eq!(parsed, configured_tenant);

        let error = runtime_tenant_id_from_lookup(|key| {
            if key == "MANDOFORGE_TENANT_ID" {
                Some("not-a-uuid".to_string())
            } else {
                None
            }
        })
        .expect_err("invalid tenant id should fail closed");
        assert!(
            error
                .to_string()
                .contains("MANDOFORGE_TENANT_ID must be a valid UUID")
        );
    }

    #[test]
    fn tenant_runtime_mode_defaults_and_parses_env_override() {
        assert_eq!(
            tenant_runtime_mode_from_lookup(|_| None).expect("default tenant mode"),
            TenantRuntimeMode::SingleRuntimeTenant
        );
        assert_eq!(
            tenant_runtime_mode_from_lookup(|key| {
                (key == "MANDOFORGE_TENANT_ROUTING_MODE").then(|| "tenant_routed".to_string())
            })
            .expect("tenant routed mode"),
            TenantRuntimeMode::TenantRouted
        );
        let error = tenant_runtime_mode_from_lookup(|key| {
            (key == "MANDOFORGE_TENANT_ROUTING_MODE").then(|| "unsafe".to_string())
        })
        .expect_err("unsupported tenant mode should fail closed");
        assert!(
            error
                .to_string()
                .contains("unsupported MANDOFORGE_TENANT_ROUTING_MODE")
        );
    }

    #[test]
    fn stage2_readiness_parses_open_completion_gaps() {
        let audit = r#"
# Stage 2 Completion Audit

## Open Completion Gaps

1. First production blocker.
2. Second controller-backed blocker.

## Completion Decision

Stage 2 is not complete.
"#;

        let gaps = parse_stage2_open_gaps(audit);

        assert_eq!(gaps.len(), 2);
        assert_eq!(gaps[0], "First production blocker.");
        assert_eq!(gaps[1], "Second controller-backed blocker.");

        let readiness = build_stage2_completion_readiness();
        assert_eq!(readiness.evidence_requirements.len(), 14);
        assert_eq!(readiness.evidence_requirements[0].id, "tenant-routing");
        assert!(
            readiness.evidence_requirements[0]
                .validation_endpoints
                .contains(&"/api/tenant-isolation/routing/validate".to_string())
        );
        assert!(
            readiness.evidence_requirements[0]
                .evidence_scripts
                .contains(&"./scripts/tenant-isolation-evidence-gate.sh".to_string())
        );
        assert!(
            readiness.evidence_requirements[0]
                .evidence_job_manifests
                .contains(
                    &"deploy/stage2-evidence/tenant-isolation-evidence-job.example.yaml"
                        .to_string()
                )
        );
        assert!(
            readiness
                .evidence_requirements
                .iter()
                .any(|requirement| requirement.id == "ui-production-polish")
        );

        let mcp = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "mcp-rollout")
            .expect("missing MCP rollout evidence requirement");
        assert!(
            mcp.required_flags
                .contains(&"RUN_STAGE2_MCP_DUE_RUN=1".to_string())
        );
        assert!(
            mcp.required_flags
                .contains(&"RUN_STAGE2_MCP_ROLLBACK=1".to_string())
        );
        assert!(
            mcp.evidence_job_manifests.contains(
                &"deploy/stage2-evidence/mcp-gateway-evidence-job.example.yaml".to_string()
            )
        );

        let eval_release = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "eval-release")
            .expect("missing eval release evidence requirement");
        assert!(
            eval_release
                .required_flags
                .contains(&"RUN_STAGE2_EVAL_RELEASE_AUTOMATION=1".to_string())
        );
        assert!(
            eval_release
                .required_flags
                .contains(&"RUN_STAGE2_EVAL_RELEASE_ROLLBACK=1".to_string())
        );
        assert!(
            eval_release.required_for_stage2_production,
            "eval/release is a Stage 2 production evidence lane"
        );
        assert!(
            !eval_release.required_for_core,
            "eval/release must not be reported as an Agent OS core runtime lane"
        );

        let managed_session = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "managed-session-restart-resume")
            .expect("missing managed-session restart/resume evidence requirement");
        assert!(
            managed_session
                .required_flags
                .contains(&"RUN_STAGE2_MANAGED_SESSION_RESTART_RESUME=1".to_string())
        );
        assert!(
            managed_session.required_flags.contains(
                &"MANDOFORGE_STAGE2_MANAGED_SESSION_RUNTIME_TARGET_ID=managed-session-runtime-prod"
                    .to_string()
            )
        );
        assert!(
            managed_session
                .required_artifacts
                .contains(&"managed-session-restart-resume-evidence.json".to_string())
        );

        let finance = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "finance-close")
            .expect("missing finance evidence requirement");
        assert!(
            finance
                .required_flags
                .contains(&"RUN_STAGE2_FINANCE_CONTROLLERS=1".to_string())
        );
        assert!(
            finance
                .required_flags
                .contains(&"RUN_STAGE2_FINANCE_EXPORT=1".to_string())
        );
        assert!(finance.required_flags.contains(
            &"FINANCE_EXPORT_DELIVERY_OBSERVER_URL=https://controller.example.com/mandoforge/finance/export/observer"
                .to_string()
        ));
        assert!(
            finance
                .required_artifacts
                .contains(&"finance-export-delivery-observer.json".to_string())
        );

        for optional_enterprise_id in [
            "tenant-routing",
            "policy-rollout",
            "vault-kms",
            "worker-remote-computer",
            "finance-close",
        ] {
            let requirement = readiness
                .evidence_requirements
                .iter()
                .find(|requirement| requirement.id == optional_enterprise_id)
                .unwrap_or_else(|| panic!("missing {optional_enterprise_id} evidence requirement"));
            assert_eq!(
                requirement.category, "enterprise_optional",
                "{optional_enterprise_id} must be an optional enterprise plugin evidence lane"
            );
            assert!(
                !requirement.required_for_core,
                "{optional_enterprise_id} must not block Agent OS core completion"
            );
            assert!(
                !requirement.required_for_stage2_production,
                "{optional_enterprise_id} must not block Stage 2 production evidence by default"
            );
            assert!(
                requirement.enterprise_optional,
                "{optional_enterprise_id} must be reported as optional enterprise evidence"
            );
        }

        for stage2_production_id in [
            "provider-rollout",
            "approval-notifications",
            "mcp-rollout",
            "eval-release",
            "observability-collector",
            "ui-production-polish",
        ] {
            let requirement = readiness
                .evidence_requirements
                .iter()
                .find(|requirement| requirement.id == stage2_production_id)
                .unwrap_or_else(|| panic!("missing {stage2_production_id} evidence requirement"));
            assert_eq!(
                requirement.category, "stage2_production",
                "{stage2_production_id} must be a Stage 2 production evidence lane"
            );
            assert!(
                requirement.required_for_stage2_production,
                "{stage2_production_id} must be enforced by the Stage 2 production evidence gate"
            );
            assert!(
                !requirement.required_for_core,
                "{stage2_production_id} must not be reported as an Agent OS core runtime lane"
            );
            assert!(
                !requirement.enterprise_optional,
                "{stage2_production_id} must not be reported as optional enterprise evidence"
            );
        }

        let managed_session = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "managed-session-restart-resume")
            .expect("missing managed-session restart/resume evidence requirement");
        assert_eq!(managed_session.category, "core_runtime");
        assert!(managed_session.required_for_core);
        assert!(managed_session.required_for_stage2_production);
        assert!(!managed_session.enterprise_optional);
    }

