    #[test]
    fn dynamic_workflow_native_dynamic_graph_models_evaluator_feedback_loop() {
        let now = Utc::now();
        let plan = DynamicWorkflowPlan {
            id: Uuid::new_v4(),
            source_work_item_id: None,
            source_session_id: None,
            objective: "Implement a milestone and verify it with external evaluators".to_string(),
            status: "approved".to_string(),
            phases: json!([
                {
                    "key": "implementation",
                    "prompt": "Implement the requested milestone."
                }
            ]),
            agent_fleet_policy: json!({
                "max_total_agents": 12,
                "max_parallel_agents": 4
            }),
            governance: default_dynamic_workflow_governance(),
            validation: default_dynamic_workflow_validation(),
            materialization: json!({
                "execution_strategy": "native_dynamic",
                "runtime_adapter": "codex_app_server",
                "runtime_mode": "dynamic_workflow"
            }),
            analysis: empty_json_object(),
            review: empty_json_object(),
            workflow_definition_id: None,
            workflow_run_id: None,
            audit_trace_id: None,
            created_at: now,
            updated_at: now,
            reviewed_at: None,
            materialized_at: None,
        };

        let graph = dynamic_workflow_plan_step_graph(&plan, "native_dynamic")
            .expect("native dynamic graph is generated");
        let steps = graph["steps"].as_array().expect("steps");
        let keys = steps
            .iter()
            .map(|step| step["key"].as_str().expect("step key"))
            .collect::<Vec<_>>();
        assert_eq!(
            keys,
            vec![
                "implement",
                "implementation-evaluator",
                "developer",
                "troubleshooter",
                "integration-tester",
                "integration-gate-keeper",
                "unexpected-error"
            ]
        );
        assert_eq!(steps[0]["start"], json!(true));
        assert_eq!(steps[1]["depends_on"], json!(["implement"]));
        assert_eq!(
            steps[2]["condition"]["path"],
            json!("/evaluation/found_gap")
        );
        assert_eq!(
            steps[3]["condition"]["path"],
            json!("/evaluation/found_issues")
        );
        assert_eq!(steps[5]["condition"]["path"], json!("/integration/no_gap"));
        assert_eq!(
            steps[6]["on_failure_of"],
            json!([
                "implement",
                "developer",
                "troubleshooter",
                "integration-tester"
            ])
        );
        assert_eq!(
            graph["dynamic_loop"]["terminal_success_step"],
            json!("integration-gate-keeper")
        );
    }

    #[tokio::test]
    async fn workflow_definition_patch_rejects_invalid_graph_without_updating() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");

        let definition: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-definitions",
                json!({
                    "name": "Editable graph workflow",
                    "entrypoint": "editable-graph-workflow",
                    "trigger_type": "manual",
                    "default_agent_id": agent.id,
                    "step_graph": {
                        "steps": [
                            {"key": "intake", "type": "agent", "start": true}
                        ]
                    },
                    "release_state": "draft"
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        let definition_id = definition["id"].as_str().expect("definition id");

        let (status, error) = request_value(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-definitions/{definition_id}"),
                json!({
                    "step_graph": {
                        "steps": [
                            {"key": "intake", "type": "agent", "start": true},
                            {"key": "draft", "type": "agent", "depends_on": ["missing-step"]}
                        ]
                    }
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(
            error["error"]
                .as_str()
                .is_some_and(|message| message.contains("unknown step missing-step"))
        );

        let unchanged: Value = request_json(
            app,
            Request::builder()
                .uri(format!("/api/workflow-definitions/{definition_id}"))
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(unchanged["name"], json!("Editable graph workflow"));
        assert_eq!(
            unchanged["step_graph"]["steps"]
                .as_array()
                .expect("steps")
                .len(),
            1
        );
    }

    #[tokio::test]
    async fn workflow_definition_patch_updates_graph_and_records_audit() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");

        let definition: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-definitions",
                json!({
                    "name": "Patchable graph workflow",
                    "entrypoint": "patchable-graph-workflow",
                    "trigger_type": "manual",
                    "default_agent_id": agent.id,
                    "step_graph": {
                        "steps": [
                            {"key": "intake", "type": "agent", "start": true}
                        ]
                    },
                    "handoff_rules": {"mode": "initial"},
                    "release_state": "draft"
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        let definition_id = definition["id"].as_str().expect("definition id");
        let created_at = definition["created_at"].clone();

        let updated: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-definitions/{definition_id}"),
                json!({
                    "name": "Patched graph workflow",
                    "step_graph": {
                        "steps": [
                            {"key": "intake", "type": "agent", "start": true},
                            {"key": "draft", "type": "agent", "depends_on": ["intake"]}
                        ]
                    }
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        assert_eq!(updated["name"], json!("Patched graph workflow"));
        assert_eq!(updated["entrypoint"], json!("patchable-graph-workflow"));
        assert_eq!(updated["handoff_rules"], json!({"mode": "initial"}));
        assert_eq!(
            updated["step_graph"]["steps"]
                .as_array()
                .expect("steps")
                .len(),
            2
        );
        assert_eq!(updated["created_at"], created_at);
        assert_ne!(updated["updated_at"], definition["updated_at"]);

        let audit_logs: Vec<AuditLog> = request_json(
            app,
            Request::builder()
                .uri("/api/audit-logs")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(audit_logs.iter().any(|log| {
            log.action == "workflow_definition.updated"
                && log.resource_id.map(|id| id.to_string()).as_deref() == Some(definition_id)
                && log.details["changed_fields"]
                    .as_array()
                    .is_some_and(|fields| fields.contains(&json!("step_graph")))
        }));
    }

    #[tokio::test]
    async fn workflow_runs_create_primary_session_and_step_runs() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");

        let definition: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-definitions",
                json!({
                    "name": "AI use case triage",
                    "entrypoint": "ai-use-case-triage",
                    "trigger_type": "manual",
                    "default_agent_id": agent.id,
                    "step_graph": {
                        "steps": [
                            {"key": "intake", "agent_role": "orchestrator"},
                            {"key": "draft", "agent_role": "writer"}
                        ]
                    },
                    "handoff_rules": {},
                    "eval_gate_refs": ["pack-regression"],
                    "release_state": "released"
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        assert_eq!(definition["name"], json!("AI use case triage"));
        assert_eq!(definition["default_agent_id"], json!(agent.id));

        let run: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-runs",
                json!({
                    "workflow_definition_id": definition["id"],
                    "title": "triage first AI use case",
                    "input_payload": {
                        "use_case_id": "AI-001",
                        "owner": "legal"
                    }
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;
        assert_eq!(run["workflow_definition_id"], definition["id"]);
        assert_eq!(run["status"], json!("queued"));
        assert!(run["primary_session_id"].as_str().is_some());
        assert!(run["root_task_grant_id"].as_str().is_some());
        assert!(run["input_digest"].as_str().is_some_and(|digest| {
            digest.starts_with("fnv1a64:") && digest.len() == "fnv1a64:0000000000000000".len()
        }));

        let session_id = run["primary_session_id"].as_str().expect("session id");
        let root_task_grant_id = run["root_task_grant_id"]
            .as_str()
            .expect("root task grant id");
        let events: Vec<SessionEvent> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{session_id}/events"))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(events.iter().any(|event| {
            event.event_type == "workflow.run.created"
                && event.payload["workflow_run_id"] == run["id"]
                && event.payload["workflow_definition_id"] == definition["id"]
        }));
        assert!(events.iter().any(|event| {
            event.event_type == "task_grant.issued"
                && event.payload["task_grant_id"] == json!(root_task_grant_id)
                && event.payload["workflow_run_id"] == run["id"]
        }));

        let initial_steps: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!(
                    "/api/workflow-runs/{}/steps",
                    run["id"].as_str().unwrap()
                ))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(initial_steps.len(), 1);
        assert_eq!(initial_steps[0]["step_key"], json!("intake"));
        assert_eq!(initial_steps[0]["session_id"], json!(session_id));
        assert_eq!(initial_steps[0]["task_grant_id"], json!(root_task_grant_id));

        let grants: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!(
                    "/api/workflow-runs/{}/task-grants",
                    run["id"].as_str().unwrap()
                ))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(grants.len(), 1);
        assert_eq!(grants[0]["id"], json!(root_task_grant_id));
        assert_eq!(grants[0]["parent_grant_id"], Value::Null);
        assert_eq!(grants[0]["status"], json!("active"));
        assert_eq!(grants[0]["memory_scope"]["mode"], json!("snapshot_only"));

        let step: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                &format!("/api/workflow-runs/{}/steps", run["id"].as_str().unwrap()),
                json!({
                    "step_key": "draft",
                    "step_type": "agent",
                    "agent_id": agent.id,
                    "session_id": session_id,
                    "task_grant_id": root_task_grant_id,
                    "status": "queued",
                    "input_payload": {"source": "workflow run test"}
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;
        assert_eq!(step["workflow_run_id"], run["id"]);
        assert_eq!(step["step_key"], json!("draft"));
        assert_eq!(step["session_id"], json!(session_id));
        assert_eq!(step["task_grant_id"], json!(root_task_grant_id));

        let listed_steps: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!(
                    "/api/workflow-runs/{}/steps",
                    run["id"].as_str().unwrap()
                ))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(listed_steps.len(), 2);
        assert!(listed_steps.iter().any(|listed| listed["id"] == step["id"]));
        assert!(
            listed_steps
                .iter()
                .any(|listed| listed["id"] == initial_steps[0]["id"])
        );

        let listed_runs: Vec<Value> = request_json(
            app,
            Request::builder()
                .uri("/api/workflow-runs")
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(listed_runs.iter().any(|listed| listed["id"] == run["id"]));
    }

    #[tokio::test]
    async fn workflow_step_completion_advances_dependency_graph() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");

        let definition: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-definitions",
                json!({
                    "name": "Dependency graph workflow",
                    "entrypoint": "dependency-graph-workflow",
                    "trigger_type": "manual",
                    "default_agent_id": agent.id,
                    "step_graph": {
                        "steps": [
                            {"key": "intake", "type": "agent", "start": true},
                            {"key": "research", "type": "agent", "depends_on": ["intake"]},
                            {"key": "draft", "type": "agent", "depends_on": ["research"]}
                        ]
                    },
                    "release_state": "released"
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        let run: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-runs",
                json!({
                    "workflow_definition_id": definition["id"],
                    "title": "advance dependency graph"
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;
        let run_id = run["id"].as_str().expect("run id");
        let root_task_grant_id = run["root_task_grant_id"]
            .as_str()
            .expect("root task grant id");

        let mut steps: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/steps"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(steps.len(), 1);
        assert_eq!(steps[0]["step_key"], json!("intake"));
        let intake_step_id = steps[0]["id"].as_str().expect("intake step id").to_string();
        let start_transitions: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/transitions"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(start_transitions.len(), 1);
        assert_eq!(start_transitions[0]["transition_type"], json!("start"));
        assert_eq!(start_transitions[0]["status"], json!("materialized"));
        assert_eq!(start_transitions[0]["to_step_key"], json!("intake"));
        assert_eq!(
            start_transitions[0]["to_step_run_id"],
            json!(intake_step_id)
        );
        let initial_graph: Value = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/graph"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(initial_graph["node_count"], json!(3));
        assert_eq!(initial_graph["status_counts"]["declared"], json!(2));
        let initial_nodes = initial_graph["nodes"].as_array().expect("graph nodes");
        let declared_research = initial_nodes
            .iter()
            .find(|node| node["step_key"] == json!("research"))
            .expect("declared research node");
        assert_eq!(declared_research["declared"], json!(true));
        assert_eq!(declared_research["step_run_id"], Value::Null);
        assert_eq!(declared_research["dependencies"], json!(["intake"]));
        let declared_draft = initial_nodes
            .iter()
            .find(|node| node["step_key"] == json!("draft"))
            .expect("declared draft node");
        assert_eq!(declared_draft["declared"], json!(true));
        assert_eq!(declared_draft["dependencies"], json!(["research"]));
        assert!(
            initial_graph["edges"]
                .as_array()
                .expect("graph edges")
                .iter()
                .any(|edge| {
                    edge["declared"] == json!(true)
                        && edge["transition_type"] == json!("declared_dependency")
                        && edge["from_step_key"] == json!("research")
                        && edge["to_step_key"] == json!("draft")
                })
        );

        let completed_intake: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-step-runs/{intake_step_id}"),
                json!({
                    "status": "completed",
                    "output_payload": {"summary": "intake complete"}
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;
        assert_eq!(completed_intake["status"], json!("completed"));
        assert!(completed_intake["completed_at"].as_str().is_some());

        steps = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/steps"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(steps.len(), 2);
        let research_step = steps
            .iter()
            .find(|step| step["step_key"] == json!("research"))
            .expect("research step should be materialized after intake");
        assert_eq!(research_step["status"], json!("queued"));
        assert_eq!(research_step["task_grant_id"], json!(root_task_grant_id));
        assert!(
            steps.iter().all(|step| step["step_key"] != json!("draft")),
            "draft must wait until research completes"
        );

        let research_step_id = research_step
            .get("id")
            .and_then(Value::as_str)
            .expect("research step id")
            .to_string();
        let dependency_transitions: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/transitions"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(dependency_transitions.iter().any(|transition| {
            transition["transition_type"] == json!("dependency")
                && transition["from_step_run_id"] == json!(intake_step_id)
                && transition["from_step_key"] == json!("intake")
                && transition["to_step_run_id"] == json!(research_step_id)
                && transition["to_step_key"] == json!("research")
                && transition["condition_payload"]["dependencies"] == json!(["intake"])
        }));
        let filtered_dependency_transitions: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!(
                    "/api/workflow-runs/{run_id}/transitions?transition_type=dependency&status=materialized&to_step_key=research&limit=1"
                ))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(filtered_dependency_transitions.len(), 1);
        assert_eq!(
            filtered_dependency_transitions[0]["to_step_run_id"],
            json!(research_step_id)
        );
        assert_eq!(
            filtered_dependency_transitions[0]["transition_type"],
            json!("dependency")
        );
        let _: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-step-runs/{research_step_id}"),
                json!({
                    "status": "completed",
                    "output_payload": {"summary": "research complete"}
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;

        steps = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/steps"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let draft_step = steps
            .iter()
            .find(|step| step["step_key"] == json!("draft"))
            .expect("draft step should be materialized after research");
        assert_eq!(draft_step["status"], json!("queued"));
        let draft_step_id = draft_step
            .get("id")
            .and_then(Value::as_str)
            .expect("draft step id")
            .to_string();
        let _: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-step-runs/{draft_step_id}"),
                json!({
                    "status": "completed",
                    "output_payload": {"summary": "draft complete"}
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;

        let completed_run: Value = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(completed_run["status"], json!("completed"));
        assert!(completed_run["completed_at"].as_str().is_some());

        let events: Vec<SessionEvent> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!(
                    "/api/sessions/{}/events",
                    completed_run["primary_session_id"].as_str().unwrap()
                ))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(events.iter().any(|event| {
            event.event_type == "workflow.step.completed"
                && event.payload["workflow_step_run_id"] == json!(draft_step_id)
        }));
        assert!(events.iter().any(|event| {
            event.event_type == "workflow.run.completed"
                && event.payload["workflow_run_id"] == completed_run["id"]
        }));
        let final_transitions: Vec<Value> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/transitions"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(final_transitions.iter().any(|transition| {
            transition["transition_type"] == json!("complete")
                && transition["from_step_run_id"] == json!(draft_step_id)
                && transition["from_step_key"] == json!("draft")
                && transition["status"] == json!("completed")
        }));
    }

    #[tokio::test]
    async fn workflow_step_failure_retries_then_compensates_and_skips_dependents() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");

        let definition: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-definitions",
                json!({
                    "name": "Retry compensation workflow",
                    "entrypoint": "retry-compensation-workflow",
                    "trigger_type": "manual",
                    "default_agent_id": agent.id,
                    "step_graph": {
                        "steps": [
                            {"key": "intake", "type": "agent", "start": true},
                            {"key": "enrich", "type": "agent", "depends_on": ["intake"], "retry": {"max_attempts": 2}},
                            {"key": "publish", "type": "agent", "depends_on": ["enrich"]},
                            {"key": "notify", "type": "agent", "depends_on": ["publish"]},
                            {
                                "key": "cleanup",
                                "type": "rollback_adapter",
                                "on_failure_of": ["enrich"],
                                "adapter": {"kind": "internal_compensation"}
                            }
                        ]
                    },
                    "release_state": "released"
                }),
                &[("x-mandoforge-roles", "admin")],
            ),
        )
        .await;
        let run: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/workflow-runs",
                json!({
                    "workflow_definition_id": definition["id"],
                    "title": "retry and compensate"
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;
        let run_id = run["id"].as_str().expect("run id");

        let steps: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/steps"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let intake_step_id = steps[0]["id"].as_str().expect("intake step id").to_string();
        let _: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-step-runs/{intake_step_id}"),
                json!({
                    "status": "completed",
                    "output_payload": {"summary": "intake complete"}
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;

        let steps: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/steps"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let enrich_step_id = steps
            .iter()
            .find(|step| step["step_key"] == json!("enrich"))
            .and_then(|step| step["id"].as_str())
            .expect("enrich step id")
            .to_string();
        let _: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-step-runs/{enrich_step_id}"),
                json!({
                    "status": "failed",
                    "output_payload": {"error": "transient upstream failure"}
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;

        let steps_after_retry: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/steps"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let enrich_attempts = steps_after_retry
            .iter()
            .filter(|step| step["step_key"] == json!("enrich"))
            .collect::<Vec<_>>();
        assert_eq!(enrich_attempts.len(), 2);
        let retry_step = enrich_attempts
            .iter()
            .find(|step| step["status"] == json!("queued"))
            .expect("retry attempt should be queued");
        assert_eq!(retry_step["input_payload"]["retry"]["attempt"], json!(2));
        assert_eq!(
            retry_step["input_payload"]["retry"]["max_attempts"],
            json!(2)
        );

        let run_after_retry: Value = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(run_after_retry["status"], json!("running"));

        let retry_step_id = retry_step["id"]
            .as_str()
            .expect("retry step id")
            .to_string();
        let transitions_after_retry: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/transitions"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(transitions_after_retry.iter().any(|transition| {
            transition["transition_type"] == json!("retry")
                && transition["from_step_run_id"] == json!(enrich_step_id)
                && transition["to_step_run_id"] == json!(retry_step_id)
                && transition["condition_payload"]["attempt"] == json!(2)
        }));

        let _: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "PATCH",
                &format!("/api/workflow-step-runs/{retry_step_id}"),
                json!({
                    "status": "failed",
                    "output_payload": {"error": "permanent upstream failure"}
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;

        let steps_after_failure: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/steps"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let publish_step = steps_after_failure
            .iter()
            .find(|step| step["step_key"] == json!("publish"))
            .expect("publish should be skipped after enrich failure");
        assert_eq!(publish_step["status"], json!("skipped"));
        assert_eq!(
            publish_step["output_payload"]["skip_reason"],
            json!("dependency_failed")
        );
        let notify_step = steps_after_failure
            .iter()
            .find(|step| step["step_key"] == json!("notify"))
            .expect("notify should be skipped after publish is skipped");
        assert_eq!(notify_step["status"], json!("skipped"));
        assert_eq!(
            notify_step["output_payload"]["skip_reason"],
            json!("dependency_failed")
        );
        let cleanup_step = steps_after_failure
            .iter()
            .find(|step| step["step_key"] == json!("cleanup"))
            .expect("cleanup should be materialized as compensation");
        assert_eq!(cleanup_step["status"], json!("queued"));
        assert_eq!(cleanup_step["step_type"], json!("rollback_adapter"));
        assert_eq!(cleanup_step["agent_id"], Value::Null);
        assert_eq!(
            cleanup_step["input_payload"]["failure_trigger"]["failed_step_key"],
            json!("enrich")
        );
        let cleanup_step_id = cleanup_step["id"]
            .as_str()
            .expect("cleanup step id")
            .to_string();

        let transitions_after_failure: Vec<Value> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/transitions"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(transitions_after_failure.iter().any(|transition| {
            transition["transition_type"] == json!("skip")
                && transition["from_step_run_id"] == json!(retry_step_id)
                && transition["to_step_key"] == json!("publish")
                && transition["status"] == json!("skipped")
        }));
        assert!(transitions_after_failure.iter().any(|transition| {
            transition["transition_type"] == json!("compensation")
                && transition["from_step_run_id"] == json!(retry_step_id)
                && transition["to_step_run_id"] == json!(cleanup_step_id)
                && transition["status"] == json!("materialized")
        }));

        let run_after_failure: Value = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(run_after_failure["status"], json!("running"));

        let compensation_result: Value = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                &format!("/api/workflow-step-runs/{cleanup_step_id}/run"),
                json!({
                    "worker_id": "rollback-adapter-worker"
                }),
                &[("x-mandoforge-roles", "operator")],
            ),
        )
        .await;
        assert_eq!(compensation_result["step"]["status"], json!("completed"));
        assert_eq!(
            compensation_result["step"]["output_payload"]["rollback_adapter"]["status"],
            json!("completed")
        );
        assert_eq!(
            compensation_result["step"]["output_payload"]["rollback_adapter"]["adapter_kind"],
            json!("internal_compensation")
        );
        let final_run: Value = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(final_run["status"], json!("failed"));
        assert!(final_run["completed_at"].as_str().is_some());

        let final_transitions: Vec<Value> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/workflow-runs/{run_id}/transitions"))
                .header("x-mandoforge-roles", "operator")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(final_transitions.iter().any(|transition| {
            transition["transition_type"] == json!("compensation")
                && transition["from_step_run_id"] == json!(cleanup_step_id)
                && transition["to_step_run_id"] == json!(cleanup_step_id)
                && transition["status"] == json!("completed")
        }));
        assert!(final_transitions.iter().any(|transition| {
            transition["transition_type"] == json!("fail")
                && transition["from_step_run_id"] == json!(cleanup_step_id)
                && transition["status"] == json!("failed")
                && transition["result_payload"]["failed_step_keys"] == json!(["enrich"])
        }));
    }

