    #[test]
    fn approval_notification_production_ops_requires_controller_when_configured() {
        let generated_at = Utc::now();
        let routing = ready_approval_notification_routing(generated_at);
        let delivery_run = ApprovalNotificationDeliveryRunRecord {
            id: Uuid::new_v4(),
            status: "delivered".to_string(),
            subject: Some("admin-1".to_string()),
            candidate_count: 1,
            delivered_count: 1,
            reserved_count: 0,
            failed_count: 0,
            skipped_count: 0,
            ran_at: generated_at,
        };
        let missing = build_approval_notification_production_ops_readiness(
            Some(&delivery_run),
            &routing,
            &[],
            generated_at,
            true,
            false,
        );
        assert_eq!(missing.status, "blocked");
        assert!(missing.production_blocked);
        assert!(missing.message.contains("controller is required"));

        let validated_audit = new_audit_log(
            None,
            "user",
            None,
            "approval.notification_ops_validation_run",
            "approval_notifications",
            None,
            json!({
                "status": "validated",
                "controller_configured": true,
                "controller_execution": {
                    "attempted": true,
                    "status": "validated",
                    "ops_id": "approval-notification-ops-1"
                },
                "checked_at": generated_at,
            }),
        );
        let ready = build_approval_notification_production_ops_readiness(
            Some(&delivery_run),
            &routing,
            &[validated_audit],
            generated_at,
            true,
            true,
        );
        assert_eq!(ready.status, "ready");
        assert!(!ready.production_blocked);
        assert!(ready.latest_controller_validated);
        assert!(ready.controller_evidence_fresh);
        assert_eq!(ready.latest_controller_age_hours, Some(0));
        assert_eq!(ready.latest_controller_status.as_deref(), Some("validated"));

        let mut stale_audit = new_audit_log(
            None,
            "user",
            None,
            "approval.notification_ops_validation_run",
            "approval_notifications",
            None,
            json!({
                "status": "validated",
                "controller_configured": true,
                "controller_execution": {
                    "attempted": true,
                    "status": "validated",
                    "ops_id": "approval-notification-ops-stale"
                },
                "checked_at": generated_at - chrono::Duration::hours(25),
            }),
        );
        stale_audit.created_at = generated_at - chrono::Duration::hours(25);
        let stale = build_approval_notification_production_ops_readiness(
            Some(&delivery_run),
            &routing,
            &[stale_audit],
            generated_at,
            true,
            true,
        );
        assert_eq!(stale.status, "blocked");
        assert!(stale.production_blocked);
        assert!(!stale.controller_evidence_fresh);
        assert_eq!(stale.latest_controller_age_hours, Some(25));
        assert!(
            stale
                .message
                .contains("approval notification ops controller evidence is stale")
        );
    }

    #[test]
    fn approval_notification_deployment_readiness_requires_controller_when_configured() {
        let generated_at = Utc::now();
        let routing = ApprovalNotificationRoutingSummary {
            status: "healthy".to_string(),
            generated_at,
            webhook_configured: true,
            slack_configured: false,
            email_relay_configured: false,
            channel_count: 1,
            persisted_policy_count: 1,
            active_policy_count: 1,
            channel_policies: vec![],
            pending_approval_count: 0,
            delegated_pending_count: 0,
            group_pending_count: 0,
            routable_pending_count: 0,
            unroutable_pending_count: 0,
            approval_group_count: 0,
            escalation_rule_count: 0,
            attention_items: vec![],
        };
        let missing = build_approval_notification_deployment_readiness(
            &[],
            &routing,
            generated_at,
            true,
            false,
        );
        assert_eq!(missing.status, "blocked");
        assert!(missing.production_blocked);
        assert!(missing.controller_required);
        assert!(!missing.controller_configured);
        assert!(missing.blocking_reasons.iter().any(|reason| {
            reason == "approval notification deployment controller is required but not configured"
        }));

        let stale_without_controller = build_approval_notification_deployment_readiness(
            &[new_audit_log(
                None,
                "user",
                None,
                "approval.notification_deployment_validation_run",
                "approval_notifications",
                None,
                json!({
                    "status": "healthy",
                    "pending_approval_count": 0,
                    "routable_pending_count": 0,
                    "unroutable_pending_count": 0,
                    "channel_count": 1,
                    "persisted_policy_count": 1,
                    "active_policy_count": 1,
                    "routing_status": "healthy",
                    "controller_required": true,
                    "controller_configured": true,
                    "controller_execution": {
                        "attempted": false,
                        "status": "skipped",
                        "reason": "controller_not_configured"
                    },
                    "checked_at": generated_at,
                }),
            )],
            &routing,
            generated_at,
            true,
            true,
        );
        assert_eq!(stale_without_controller.status, "blocked");
        assert!(stale_without_controller.production_blocked);
        assert!(!stale_without_controller.latest_controller_validated);

        let mut controller_audit = new_audit_log(
            None,
            "user",
            None,
            "approval.notification_deployment_validation_run",
            "approval_notifications",
            None,
            json!({
                "status": "healthy",
                "pending_approval_count": 0,
                "routable_pending_count": 0,
                "unroutable_pending_count": 0,
                "channel_count": 1,
                "persisted_policy_count": 1,
                "active_policy_count": 1,
                "routing_status": "healthy",
                "controller_required": true,
                "controller_configured": true,
                "controller_execution": {
                    "attempted": true,
                    "status": "validated",
                    "deployment_id": "approval-notification-deployment-1"
                },
                "checked_at": generated_at,
            }),
        );
        controller_audit.created_at = generated_at;
        let ready = build_approval_notification_deployment_readiness(
            &[controller_audit.clone()],
            &routing,
            generated_at,
            true,
            true,
        );
        assert_eq!(ready.status, "ready");
        assert!(!ready.production_blocked);
        assert_eq!(ready.latest_controller_status.as_deref(), Some("validated"));
        assert!(ready.latest_controller_validated);
        assert!(ready.controller_evidence_fresh);
        assert_eq!(ready.latest_controller_age_hours, Some(0));
        assert_eq!(ready.controller_execution_count, 1);
        assert_eq!(ready.controller_failed_count, 0);

        let mut stale_controller_audit = controller_audit;
        stale_controller_audit.created_at = generated_at - chrono::Duration::hours(25);
        let stale = build_approval_notification_deployment_readiness(
            &[stale_controller_audit],
            &routing,
            generated_at,
            true,
            true,
        );
        assert_eq!(stale.status, "blocked");
        assert!(stale.production_blocked);
        assert!(stale.latest_controller_validated);
        assert!(!stale.controller_evidence_fresh);
        assert_eq!(stale.latest_controller_age_hours, Some(25));
        assert!(stale.blocking_reasons.iter().any(|reason| {
            reason == "approval notification deployment controller evidence is stale"
        }));
    }

    #[tokio::test]
    async fn approval_notification_channel_policy_is_persisted_and_fail_closed_without_endpoint() {
        let app = test_app().await;
        let policy: ApprovalNotificationChannelPolicy = request_json(
            app.clone(),
            json_request_with_headers(
                "POST",
                "/api/approvals/notification-channel-policies",
                json!({
                    "name": "high-risk-webhook-policy",
                    "channel": "webhook",
                    "risk_filter": "high",
                    "target_env": "MANDOFORGE_TEST_APPROVAL_WEBHOOK_URL"
                }),
                &[
                    ("x-mandoforge-subject", "admin-1"),
                    ("x-mandoforge-roles", "admin"),
                ],
            ),
        )
        .await;
        assert_eq!(policy.status, "active");
        assert_eq!(policy.channel, "webhook");

        let policies: Vec<ApprovalNotificationChannelPolicy> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/approvals/notification-channel-policies")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(policies.len(), 1);

        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");
        let session: Session = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/sessions",
                json!({"agent_id": agent.id, "title": "approval policy"}),
            ),
        )
        .await;
        let approval_result: Value = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/tools/approval.request/execute",
                json!({
                    "session_id": session.id,
                    "args": {
                        "action": "manual.policy_review",
                        "risk_level": "high",
                        "reason": "Policy routed approval.",
                        "approver_subject": "approver-1"
                    }
                }),
            ),
        )
        .await;
        let approval_id = approval_result["approval_id"]
            .as_str()
            .expect("approval id");

        let summary: ApprovalNotificationRoutingSummary = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/approvals/notification-routing/summary")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(summary.persisted_policy_count, 1);
        assert_eq!(summary.active_policy_count, 1);
        assert_eq!(summary.channel_count, 0);
        assert_eq!(summary.status, "action_required");

        let deployment_validation: ApprovalNotificationDeploymentValidationRun = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/approvals/notifications/deployment/validate")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(deployment_validation.status, "blocked");
        assert_eq!(deployment_validation.channel_count, 0);
        assert_eq!(deployment_validation.active_policy_count, 1);
        assert_eq!(deployment_validation.unroutable_pending_count, 1);

        let delivery: ApprovalNotificationDelivery = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/approvals/{approval_id}/deliver"))
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(delivery.status, "reserved");
        assert!(!delivery.delivered);
        assert_eq!(delivery.channel_deliveries.len(), 1);
        assert_eq!(delivery.channel_deliveries[0].policy_id, Some(policy.id));
        assert!(!delivery.channel_deliveries[0].target_configured);

        let run: ApprovalNotificationDeliveryRun = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/approvals/notifications/run")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(run.status, "reserved");
        let run_summary: ApprovalNotificationDeliveryRunSummary = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/approvals/notifications/runs")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(run_summary.production_ops.status, "blocked");
        assert!(run_summary.production_ops.production_blocked);
        assert_eq!(run_summary.production_ops.channel_count, 0);
        assert_eq!(run_summary.deployment_readiness.status, "blocked");
        assert!(run_summary.deployment_readiness.production_blocked);
        assert!(!run_summary.deployment_readiness.deployment_validated);
        assert!(run_summary.attention_items.iter().any(|item| {
            item.kind == "approval_notification_production_blocked" && item.severity == "critical"
        }));
        assert!(run_summary.attention_items.iter().any(|item| {
            item.kind == "approval_notification_deployment_validation_blocked"
                && item.severity == "critical"
        }));

        let archived: ApprovalNotificationChannelPolicy = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!(
                    "/api/approvals/notification-channel-policies/{}/archive",
                    policy.id
                ))
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(archived.status, "archived");

        let audit_logs: Vec<AuditLog> = request_json(
            app,
            Request::builder()
                .uri("/api/audit-logs")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(audit_logs.iter().any(|log| {
            log.action == "approval.notification_channel_policy_created"
                && log.details.get("target_url").is_none()
        }));
        assert!(
            audit_logs
                .iter()
                .any(|log| log.action == "approval.notification_channel_policy_archived")
        );
        assert!(
            audit_logs
                .iter()
                .any(|log| log.action == "approval.notification_deployment_validation_run")
        );
    }

