    #[tokio::test]
    async fn approving_file_write_resumes_tool_and_creates_artifact() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");
        let session: Session = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/sessions",
                json!({"agent_id": agent.id, "title": "file write approval"}),
            ),
        )
        .await;

        let content = "# Diagnostics\n\nApproved write.";
        let approval_result: Value = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/tools/file.write/execute",
                json!({
                    "session_id": session.id,
                    "args": {
                        "path": "diagnostics.md",
                        "content": content
                    }
                }),
            ),
        )
        .await;
        let approval_id = approval_result["approval_id"]
            .as_str()
            .expect("approval id");

        let approved: Approval = request_json(
            app.clone(),
            approve_request(format!("/api/approvals/{approval_id}/approve")),
        )
        .await;
        assert_eq!(approved.status, "approved");

        let written = tokio::fs::read_to_string(
            test_workspace_root()
                .join(session.id.to_string())
                .join("diagnostics.md"),
        )
        .await
        .expect("approved file.write created workspace file");
        assert_eq!(written, content);

        let artifacts: Vec<Artifact> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/artifacts", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(artifacts.iter().any(|artifact| {
            artifact.name == "diagnostics.md" && artifact.path.as_deref() == Some("diagnostics.md")
        }));

        let tool_calls: Vec<ToolCall> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/tool-calls", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(tool_calls.iter().any(|call| {
            call.tool_name == "file.write"
                && call.status == "completed"
                && call
                    .result
                    .as_ref()
                    .and_then(|result| result["path"].as_str())
                    == Some("diagnostics.md")
        }));

        let queued_resume_jobs = session_loop_jobs_for_session(app.clone(), session.id).await;
        let events: Vec<SessionEvent> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let execution_completed_event = events
            .iter()
            .find(|event| event.event_type == "execution.completed")
            .expect("inline approved execution should be a durable completion event");
        assert!(
            queued_resume_jobs.iter().any(|job| {
                job.status == SessionLoopJobStatus::Queued
                    && job.reason == "approved execution completed"
                    && job.trigger_event_id == Some(execution_completed_event.id)
            }),
            "approved inline execution should resume through the session-loop queue: {queued_resume_jobs:?}"
        );
        let completed_resume =
            run_next_session_loop_job(app.clone(), session.id, "file-write-resume-worker").await;
        assert_eq!(completed_resume.status, SessionLoopJobStatus::Completed);

        let events_after_resume: Vec<SessionEvent> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(
            events_after_resume
                .iter()
                .any(|event| event.event_type == "tool.result")
        );
        assert!(
            events_after_resume
                .iter()
                .any(|event| event.event_type == "artifact.created")
        );
        assert!(events_after_resume.iter().any(|event| {
            event.event_type == "llm.request"
                && event.payload["context"]["approved_tool_result_count"] == json!(1)
        }));
        assert!(events_after_resume.iter().any(|event| {
            event.event_type == "session.loop.idle"
                && event.payload["reason"] == json!("provider tool loop idled")
        }));
        assert!(events_after_resume.iter().any(|event| {
            event.event_type == "execution.completed"
                && event.payload["reason"] == json!("approved execution completed")
        }));
    }

    #[tokio::test]
    async fn rejecting_approval_records_tool_result_and_resumes_session_loop() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");
        let session: Session = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/sessions",
                json!({"agent_id": agent.id, "title": "file write rejection"}),
            ),
        )
        .await;

        let approval_result: Value = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/tools/file.write/execute",
                json!({
                    "session_id": session.id,
                    "args": {
                        "path": "rejected.md",
                        "content": "should not be written"
                    }
                }),
            ),
        )
        .await;
        let approval_id = approval_result["approval_id"]
            .as_str()
            .expect("approval id");

        let rejected: Approval = request_json(
            app.clone(),
            approve_request(format!("/api/approvals/{approval_id}/reject")),
        )
        .await;
        assert_eq!(rejected.status, "rejected");

        let events: Vec<SessionEvent> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let approval_rejected_event = events
            .iter()
            .find(|event| event.event_type == "approval.rejected")
            .expect("approval rejection should be a durable event");
        assert!(events.iter().any(|event| {
            event.event_type == "tool.result"
                && event.payload["content"]["approval"] == json!("rejected")
        }));
        assert!(events.iter().any(|event| {
            event.event_type == "agent.tool_result"
                && event.payload["content"]["approval"] == json!("rejected")
        }));

        let tool_calls: Vec<ToolCall> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/tool-calls", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(tool_calls.iter().any(|call| {
            call.tool_name == "file.write"
                && call.status == "denied"
                && call
                    .result
                    .as_ref()
                    .and_then(|result| result["approval"].as_str())
                    == Some("rejected")
        }));

        let queued_resume_jobs = session_loop_jobs_for_session(app.clone(), session.id).await;
        assert!(
            queued_resume_jobs.iter().any(|job| {
                job.status == SessionLoopJobStatus::Queued
                    && job.reason == "approval rejected"
                    && job.trigger_event_id == Some(approval_rejected_event.id)
            }),
            "rejected approval should resume through the session-loop queue: {queued_resume_jobs:?}"
        );

        let completed_resume =
            run_next_session_loop_job(app.clone(), session.id, "approval-reject-resume-worker")
                .await;
        assert_eq!(completed_resume.status, SessionLoopJobStatus::Completed);

        let events_after_resume: Vec<SessionEvent> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(events_after_resume.iter().any(|event| {
            event.event_type == "llm.request"
                && event.payload["context"]["rejected_tool_result_count"] == json!(1)
        }));
        assert!(events_after_resume.iter().any(|event| {
            event.event_type == "agent.final"
                && event
                    .payload
                    .get("message")
                    .and_then(Value::as_str)
                    .is_some_and(|message| message.contains("Approval rejected"))
        }));
    }

    #[tokio::test]
    async fn approval_modify_updates_waiting_tool_args_before_approve() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let agent = agents.first().expect("seeded agent");
        let session: Session = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/sessions",
                json!({"agent_id": agent.id, "title": "approval modify"}),
            ),
        )
        .await;

        let approval_result: Value = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/tools/file.write/execute",
                json!({
                    "session_id": session.id,
                    "args": {
                        "path": "before.md",
                        "content": "before"
                    }
                }),
            ),
        )
        .await;
        let approval_id = approval_result["approval_id"]
            .as_str()
            .expect("approval id");

        let modified: Approval = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/approvals/{approval_id}/modify"))
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "approver-1")
                .header("x-mandoforge-roles", "approver")
                .body(Body::from(
                    json!({
                        "args": {
                            "path": "after.md",
                            "content": "after"
                        },
                        "comment": "tighten file name before approval"
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(modified.status, "pending");
        assert_eq!(
            modified.decision_payload["modified_args"]["path"],
            "after.md"
        );

        let tool_calls: Vec<ToolCall> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/tool-calls", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let file_write = tool_calls
            .iter()
            .find(|call| call.tool_name == "file.write")
            .expect("file.write tool call");
        assert_eq!(file_write.args["path"], "after.md");

        let approved: Approval = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/approvals/{approval_id}/approve"))
                .header("x-mandoforge-subject", "approver-1")
                .header("x-mandoforge-roles", "approver")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(approved.status, "approved");

        let written = tokio::fs::read_to_string(
            test_workspace_root()
                .join(session.id.to_string())
                .join("after.md"),
        )
        .await
        .expect("approved modified file.write created workspace file");
        assert_eq!(written, "after");
        assert!(
            tokio::fs::metadata(
                test_workspace_root()
                    .join(session.id.to_string())
                    .join("before.md"),
            )
            .await
            .is_err(),
            "original unmodified file should not be written"
        );

        let events: Vec<SessionEvent> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(
            events
                .iter()
                .any(|event| event.event_type == "approval.modified")
        );
    }

